import json,statistics,re
from pathlib import Path
out=Path('docs/evidence/today-performance-2026-10-23')
def read(name):return json.loads((out/name).read_text())
def values(rows,key,field='usable_ms'):return [r[field] for r in rows if r.get('scenario')==key and r.get(field) is not None]
def dist(v):return f"{statistics.median(v):.0f} [{min(v):.0f}–{max(v):.0f}]"
b=read('baseline-browser.json');a=read('after-browser.json');keys=list(dict.fromkeys(r['scenario'] for r in b));lines=['# Matched measured results','','All durations are milliseconds. Brackets show min–max; the right endpoint is the observed maximum. These small samples do not estimate production percentiles. Every retained ordinary readiness trial reached editable load/repetition inputs and an enabled Save action. Filling the same manual draft is part of the readiness measurement; no set was saved.','','## Ordinary navigation','','Five serial trials per case and revision; API process primed by the separate API batch. Each case uses one fresh browser context: trial 1 is its first page, trials 2–5 reuse that context with a new page and retained occurrence selection. Next production process remains running throughout the matrix. Browser work waits for network idle only after the readiness timestamp, to drain background work before the next trial.','','| Scenario | Visible median before → after | Usable before median [range] | Usable after median [range] | Observed max change |','|---|---:|---:|---:|---:|']
for k in keys:
 bv=values(b,k);av=values(a,k);lines.append(f"| {k} | {statistics.median(values(b,k,'visible_ms')):.0f} → {statistics.median(values(a,k,'visible_ms')):.0f} | {dist(bv)} | {dist(av)} | {(max(av)/max(bv)-1)*100:+.1f}% |")
lines+=['','[Before raw](baseline-browser.json) · [After raw](after-browser.json)','','## Verified process/browser cold','','Three independent frontend/API process starts and fresh browser contexts per case and revision. Startup/readiness probes precede the navigation clock. Every run verifies unique API response marker, live frontend listening PID/worktree and BUILD_ID. PostgreSQL and filesystem caches were not cleared.','','| Scenario | Before median [range] | After median [range] |','|---|---:|---:|']
bc=read('baseline-cold-browser.json');ac=read('after-cold-browser.json')
for k in dict.fromkeys(r['scenario'] for r in bc):lines.append(f'| {k} | {dist(values(bc,k))} | {dist(values(ac,k))} |')
lines+=['','[Before raw](baseline-cold-browser.json) · [After raw](after-cold-browser.json)','','The 7,353 ms Customized-small candidate cold sample is retained. Its visible-workout timestamp is 6,849 ms. Its Today-page JavaScript resource spans about 3,251 ms from resource initiation to response end, with other shared chunks around 1.9 s. API requests occupy a smaller later portion of this navigation. These observations locate a cold asset/client-bootstrap window; they do not establish its causal source.','','## Direct API','','Five serial HTTP requests per scenario and revision, using the real API and PostgreSQL.','','| Scenario | Before median [range] | After median [range] |','|---|---:|---:|']
bapi=read('baseline-api.json');aapi=read('after-api.json')
for k in keys:lines.append(f'| {k} | {dist(values(bapi,k,"ms"))} | {dist(values(aapi,k,"ms"))} |')
lines+=['','[Before raw](baseline-api.json) · [After raw](after-api.json)','','## API work per request','','The following measurements use the first five scenario-tagged Today requests in each instrumentation file: exactly the direct API batch above. Phases are inclusive and overlap; do not add them.','']
phases={}
for label in ['baseline','after']:
 rows=[json.loads(x) for x in Path(f'.qualification/api-timings-{label}.jsonl').read_text().splitlines()];selected=[]
 for k in keys:
  own=[r for r in rows if r['path']=='/workout/today' and r.get('scenario')==k][:5];assert len(own)==5,(label,k,len(own));selected.extend(own)
 phases[label]=selected;(out/f'{label}-api-phases.json').write_text(json.dumps(selected,indent=2))
rows={label:[r for r in phases[label] if r['scenario']=='authored-large-inprogress'] for label in phases}
lines+=['Authored large in-progress, n=5:','','| Measure | Before median | After median |','|---|---:|---:|']
for field,label in [('total_ms','Total ms'),('sql_count','SQL statements'),('sql_ms','SQL execution ms'),('calibration_sql_count','Calibration SELECTs')]:lines.append(f"| {label} | {statistics.median([r[field] for r in rows['baseline']]):.1f} | {statistics.median([r[field] for r in rows['after']]):.1f} |")
for phase,label in [('app.workout_load_state._all_groups','History grouping'),('app.workout_load_state.source_scope','Source scope, load-state binding'),('app.workout_load_state.find_calibration','Calibration lookup'),('app.workout_load_state._source_warmup_protocol','Source warm-up protocol read'),('app.workout_load_state._warmup_guidance','Per-slot warm-up calculation/assembly'),('app.workout_authored.project_authored_load_feedback','Per-slot load feedback projection')]:
 def pstat(label,field):return statistics.median(r['phases'].get(phase,{}).get(field,0) for r in rows[label])
 lines.append(f'| {label}: calls / ms | {pstat("baseline","calls"):.0f} / {pstat("baseline","ms"):.1f} | {pstat("after","calls"):.0f} / {pstat("after","ms"):.1f} |')
lines+=['','[Before phase samples](baseline-api-phases.json) · [After phase samples](after-api-phases.json). Calibration report rows are **zero** in all eight ordinary cases; absence lookup is measured, rather than calibration-heavy version history. Dedicated runtime journeys cover saved calibration and qualified-history precedence. The standalone pre-change source-protocol probe is [recorded separately](baseline-source-warmup.json).','','## Representative request waterfall','','Authored large in-progress: select the median-usable trial within each five-trial batch. Start offsets are relative to the first resource in that navigation; duration is resource response end minus request start. Background endpoints may finish after usable controls.','','| Request | Before start / duration | After start / duration |','|---|---:|---:|']
def network(rows,key):
 r=sorted([r for r in rows if r['scenario']==key],key=lambda r:r['usable_ms'])[2];zero=min(x['start_ms'] for x in r['network']);result={}
 for x in r['network']:
  if x['path'].startswith('/api/'):
   path=re.sub(r'/workout/[^/]+/(progress|summary)',r'/workout/<occurrence>/\1',x['path']);result[path]=(x['start_ms']-zero,max(0,x['response_end_ms']-max(0,x['request_ms'])))
 return result
bn=network(b,'authored-large-inprogress');an=network(a,'authored-large-inprogress')
for path in dict.fromkeys([*bn,*an]):
 def cell(d):return f'{d[path][0]:.0f} / {d[path][1]:.0f}' if path in d else '—'
 lines.append(f'| {path} | {cell(bn)} | {cell(an)} |')
lines+=['','## Explicit first-use construction','','Three unique fresh accounts per mode and revision. Construction uses the existing injected Monday planning clock, with a coherent Mon/Wed/Fri week; ordinary loads use actual Friday. Authored preview then `/plan/generate-week` activation and Customized proposal/challenge/accept/activation invoke the real application and PostgreSQL through TestClient. Their timing excludes HTTP transport and browser rendering; it must not be compared directly to the ordinary HTTP/API table. All phase calls returned 200.','','| Mode / phase | Before median [range] | After median [range] |','|---|---:|---:|']
for mode in ['authored','customized']:
 br=read(f'baseline-{mode}-construction.json');ar=read(f'after-{mode}-construction.json')
 for phase in dict.fromkeys(r['phase'] for r in br):lines.append(f'| {mode} / {phase} | {dist([r["ms"] for r in br if r["phase"]==phase])} | {dist([r["ms"] for r in ar if r["phase"]==phase])} |')
bf=read('baseline-first-browser.json');af=read('after-first-browser.json');lines+=['',f'First navigation to the newly activated Authored plan through the real production frontend, n=3 unique accounts each: usable {dist([r["usable_ms"] for r in bf])} before, {dist([r["usable_ms"] for r in af])} after. The browser opens the actual Friday response, independent of the Monday construction clock.','','A separate three-account no-plan Today probe returned 404 in both revisions. That is an empty state, not first-plan construction or a slow-workout success. See [before](baseline-first-use.json) / [after](after-first-use.json).','','## Customized counterbalanced follow-up','','The initial unfavorable Customized-large API samples remain in the direct API table. Four quiet API-only ABBA process blocks use the same two ordinary accounts; each block excludes one startup warm-up request per path and retains five measured requests per path.','','| Scenario | Base block 1 | Candidate block 2 | Candidate block 3 | Base block 4 |','|---|---:|---:|---:|---:|']
r=read('customized-abba-api.json')
for k in ['customized-large-unstarted','customized-large-inprogress']:
 vals=[dist([x['ms'] for x in r if x['scenario']==k and x['block']==block and not x['warmup_excluded']]) for block in range(1,5)];lines.append('| '+k+' | '+' | '.join(vals)+' |')
lines+=['','The initial slowdown does not reproduce consistently by source across these blocks. Both sources vary with block/order. This supports a variability limitation; it does not prove its exact cause or establish absence of every regression. SQL counts remain 19/22 for unstarted/in-progress and no Authored snapshot/protocol/calibration work enters these Customized paths. [All ABBA samples, including warm-ups](customized-abba-api.json).']
p=out/'customized-cold-abba.json'
if p.exists():
 lines+=['','Additional four cold-browser ABBA trials retain the original cold outlier and add two independent trials per source:','','| Block | Source | Visible | Usable |','|---|---|---:|---:|']
 for r in read(p.name):lines.append(f'| {r["block"]} | {r["source"]} | {r["visible_ms"]:.0f} | {r["usable_ms"]:.0f} |')
 lines+=['','[Additional cold ABBA raw](customized-cold-abba.json). These samples supplement the original n=3 matrix; they do not replace it. Both additional candidate observations are slower than both base observations. A possible cold-startup regression remains unresolved; the initial 7,353 ms sample is retained. The production Today page chunk grew from 96,281 to 99,848 bytes (+3,567 / 3.7%); file size is observed, not a proven cause.']
lines+=['','## Targets and preservation','','The predeclared local targets were usable controls within 2 s warm / 5 s process-browser cold, and at least 25% lower observed maximum where a bottleneck was demonstrated. The 2 s target is unmet for large-history Authored navigation. The 5 s cold target is not uniformly met, including the retained 7,353 ms Customized sample. Ordinary large-Authored unstarted observed maximum improves 37%; in-progress improves 11%, below the 25% maximum target despite a lower median. These are partial performance gains, not uniform target acceptance.','','All 24 complete Today/progress/summary JSON payloads compare exactly across the same eight ordinary accounts before intentional runtime-journey writes. All ten scoped training/presentation table hashes and counts match, and the eight ordinary account rows also compare unchanged privately. [Preservation proof](preservation.json). Fresh first-use and dedicated runtime accounts append legitimate synthetic rows outside that scope.','','An earlier cold attempt accepted an existing owned warm listener after port-bind failure. Those invalid samples were removed from the public results and rerun with fatal occupied-port/process checks, a unique API response marker and live frontend PID/worktree/BUILD_ID verification. No invalid cold sample contributes to these tables.']
lines+=['','## Preconditions and limits','','The browser harness stores the synthetic token and the existing same-day soreness-skip key before navigation. Thus readiness is measured after that optional check-in was explicitly skipped; soreness interaction latency is outside these numbers. No two-minute Today delay was reproduced. All accounts/data are synthetic, the network is native loopback, and server/browser processes share this ARM64 production host with uncontrolled background load and warm filesystem/PostgreSQL caches. Chromium viewport results do not qualify physical iPhone Safari, keyboard, focus or background suspension.','','Runtime resource qualification retains inherited `/favicon.ico` and `/programs?_rsc` 404s. The baseline already links to `/programs` in `components/app-shell.tsx:15` while lacking an index route; resource/console paths remain in the journey evidence. These are remaining navigation/resource defects; console output is not described as clean. Intentional response-loss injections also produce expected `net::ERR_FAILED` messages.']
(out/'RESULTS.md').write_text('\n'.join(lines)+'\n');print('Generated RESULTS.md and 80 direct API phase samples')
